#ifdef GL_ES
precision mediump float;
#endif

#define PI        3.1415926535
#define TWO_PI    6.2831853071

// Raymarch parameters
#define MAX_STEPS 64
#define MAX_DIST  15.0
#define EPSILON   0.0001

// Tube geometry
#define TUBE_RADIUS 0.03   // Physical tube radius
#define ROT_SPEED   4.0    // Local spin speed (wire twisting)

//---------------------------------------------------------
// Rotation matrix helpers
//---------------------------------------------------------
mat3 rotateX(float a)
{
    float c = cos(a), s = sin(a);
    return mat3(
        1.0,  0.0,  0.0,
        0.0,   c, -s,
        0.0,   s,  c
    );
}
mat3 rotateY(float a)
{
    float c = cos(a), s = sin(a);
    return mat3(
         c, 0.0, s,
         0.0, 1.0, 0.0,
        -s, 0.0, c
    );
}
mat3 rotateZ(float a)
{
    float c = cos(a), s = sin(a);
    return mat3(
         c, -s,  0.0,
         s,  c,  0.0,
        0.0, 0.0, 1.0
    );
}

//---------------------------------------------------------
// Camera rotation: baseYaw plus mouse-based yaw/pitch
//---------------------------------------------------------
mat3 getCameraRotation(vec4 mouse, vec2 resolution)
{
    // Convert mouse coords to [-0.5..+0.5]
    vec2 d = (mouse.xy - 0.5 * resolution) / resolution;

    // Base yaw
    float baseYaw = 0.0;

    // Add mouse yaw/pitch
    float yaw   = baseYaw + d.x * PI;
    float pitch = d.y * PI;

    // Negative sign => "drag direction"
    mat3 rot = rotateY(-yaw) * rotateX(-pitch);
    return rot;
}

//---------------------------------------------------------
// DistID: holds distance + which wire + which knot
//---------------------------------------------------------
struct DistID {
    float dist;    // nearest distance
    float wireId;  // which wire (1 or 2)
    float knotId;  // which knot (0=Trefoil, 1=NewArcs, 2=Ring)
};

//---------------------------------------------------------
// Twist amounts per knot
//---------------------------------------------------------
float getKnotTwists(int knotIndex)
{
    if (knotIndex == 0) return 4.0; // Trefoil
    if (knotIndex == 1) return 10.0; // arcs
    return 12.0;                      // ring
}

//---------------------------------------------------------
// Convert raw param 't' to [0..1] for each knot
//---------------------------------------------------------
float getNormalizedParam(float t, int knotIndex)
{
    // arcs => t in [0..4]
    if(knotIndex == 1) return t / 4.0;

    // trefoil & ring => t in [0..2π]
    return t / TWO_PI;
}

//=========================================================
// TREFOIL KNOT
//=========================================================
vec3 getTrefoilBasePos(float t)
{
    float s = 0.15;
    return s * vec3(
        sin(t) + 2.0*sin(2.0*t),
        cos(t) - 2.0*cos(2.0*t),
        -sin(3.0*t)
    );
}
vec3 getTrefoilTangent(float t)
{
    float s = 0.15;
    float dx = cos(t) + 4.0*cos(2.0*t);
    float dy = -sin(t) + 4.0*sin(2.0*t);
    float dz = -3.0*cos(3.0*t);
    return normalize(s * vec3(dx, dy, dz));
}

//=========================================================
// RING (Torus)
//=========================================================
vec3 getRingBasePos(float t)
{
    float R = 0.26;
    return vec3(R*cos(t), R*sin(t), 0.0);
}
vec3 getRingTangent(float t)
{
    float R = 0.26;
    return normalize(vec3(-R*sin(t), R*cos(t), 0.0));
}

//=========================================================
// HALF-SIZE CUBE-STEP ARCS
//=========================================================
vec3 getCubeArcsBasePos(float t)
{
    float T = mod(t, 4.0);
    float I = floor(T);
    float s = fract(T);
    float angle;
    vec3 p = vec3(0.0);

    if(I < 0.5)
    {
        // front arc => [0..1]
        angle = -PI*0.5 + PI*s;
        p = vec3(0.25*cos(angle), 0.25*sin(angle), 0.25);
    }
    else if(I < 1.5)
    {
        // top arc => [1..2], rotate +90° around Y
        angle = PI*s;
        p = vec3(-0.25*cos(angle), 0.25, 0.25*sin(angle));
        p = rotateY(PI*0.5) * p;
    }
    else if(I < 2.5)
    {
        // back arc => [2..3]
        angle = -PI*0.5 + PI*s;
        p = vec3(0.25*cos(angle), 0.25*sin(angle), -0.25);
    }
    else
    {
        // bottom arc => [3..4], rotate +90° around Y
        angle = PI*s;
        p = vec3(-0.25*cos(angle), -0.25, 0.25*sin(angle));
        p = rotateY(PI*0.5) * p;
    }

    return p;
}
vec3 getCubeArcsTangent(float t)
{
    float eps = 0.0001;
    vec3 fwd = getCubeArcsBasePos(t + eps);
    vec3 bwd = getCubeArcsBasePos(t - eps);
    return normalize(fwd - bwd);
}

//---------------------------------------------------------
// Gather basePos + tangent for each knot
//---------------------------------------------------------
void getKnotFrame(
    float t, int knotIndex,
    out vec3 basePos, out vec3 tangent,
    out vec3 normal,  out vec3 binormal)
{
    // 1) Swap Trefoil (was index=0) with Ring (was index=2).
    if(knotIndex == 0)
    {
        // Ring (Torus) on the left
        basePos = getRingBasePos(t);
        tangent = getRingTangent(t);
    }
    else if(knotIndex == 1)
    {
        // Arcs in the middle
        basePos = getCubeArcsBasePos(t);
        tangent = getCubeArcsTangent(t);
    }
    else
    {
        // Trefoil on the right
        basePos = getTrefoilBasePos(t);
        tangent = getTrefoilTangent(t);
    }

    // 2) (Optional) rotate the middle knot if you want
    if(knotIndex == 1)
    {
        // Example code from your snippet:
        basePos = rotateZ(PI/3.2) * basePos;
        tangent = rotateZ(PI/3.2) * tangent;

        basePos = rotateY(PI/4.2) * basePos;
        tangent = rotateY(PI/4.2) * tangent;

        basePos = rotateX(PI/1.2) * basePos;
        tangent = rotateX(PI/1.)  * tangent;
    }

    // 3) Build normal & binormal
    vec3 up = vec3(0.0, 1.0, 0.0);
    normal   = normalize(cross(tangent, up));
    binormal = normalize(cross(tangent, normal));
}

//---------------------------------------------------------
// Evaluate wire center
//---------------------------------------------------------
vec3 evalWirePos(float t, int knotIndex, float wireId, float xOffset, float time)
{
    vec3 basePos, tangent, normal, binormal;
    getKnotFrame(t, knotIndex, basePos, tangent, normal, binormal);

    float u = getNormalizedParam(t, knotIndex);
    float twists = getKnotTwists(knotIndex);

    float phaseShift = (wireId < 1.5)? 0.0 : PI;
    float twistAngle = time * ROT_SPEED 
                     + twists * (u * TWO_PI)
                     + phaseShift;

    vec3 offset = TUBE_RADIUS * (
        cos(twistAngle)*normal +
        sin(twistAngle)*binormal
    );

    // shift horizontally for the 3 knots
    basePos.x += xOffset;

    return basePos + offset;
}

// Evaluate wire pos & derivative
void evalWirePosDeriv(
    float t, int knotIndex, float wireId, float xOffset, float time,
    out vec3 pos, out vec3 dpdt
)
{
    pos = evalWirePos(t, knotIndex, wireId, xOffset, time);
    float eps = 0.0001;
    vec3 fwd = evalWirePos(t+eps, knotIndex, wireId, xOffset, time);
    vec3 bwd = evalWirePos(t-eps, knotIndex, wireId, xOffset, time);
    dpdt = (fwd - bwd) / (2.0*eps);
}

//---------------------------------------------------------
// Distance from p to a single wire
//---------------------------------------------------------
float distanceToWire(vec3 p, int knotIndex, float wireId, float xOffset, float time)
{
    float bestT = 0.0;
    float bestDist2 = 1e6;

    float maxRange = (knotIndex == 1) ? 4.0 : TWO_PI;

    // Coarse search
    for(int i=0; i<12; i++)
    {
        float tt = float(i)*(maxRange/12.0);
        vec3 c   = evalWirePos(tt, knotIndex, wireId, xOffset, time);
        float d2 = dot(p - c, p - c);
        if(d2 < bestDist2)
        {
            bestDist2 = d2;
            bestT = tt;
        }
    }

    // Newton refine
    float tCur = bestT;
    for(int iter=0; iter<3; iter++)
    {
        vec3 c, dc;
        evalWirePosDeriv(tCur, knotIndex, wireId, xOffset, time, c, dc);
        vec3 diff = c - p;
        float fPrime  = dot(diff, dc);
        float fSecond = dot(dc, dc);
        if(abs(fSecond) < 1e-12) break;
        float delta = fPrime / fSecond;
        tCur -= delta;

        // Wrap around param domain
        if(tCur < 0.0)      tCur += maxRange;
        if(tCur >= maxRange) tCur -= maxRange;
    }

    vec3 cFinal = evalWirePos(tCur, knotIndex, wireId, xOffset, time);
    return length(p - cFinal);
}

//---------------------------------------------------------
// Distance to all wires, track wire + knot
//---------------------------------------------------------
DistID distanceToAllWires(vec3 p, float time)
{
    DistID best;
    best.dist   = 1e6;
    best.wireId = -1.0;
    best.knotId = -1.0;

    // 3 knots (k=0..2), each with wire=1..2
    for(int k=0; k<3; k++)
    {
        float xOffset = float(k-1)*1.2; 
        for(int w=1; w<=2; w++)
        {
            float d = distanceToWire(p, k, float(w), xOffset, time);
            if(d < best.dist)
            {
                best.dist   = d;
                best.wireId = float(w);
                best.knotId = float(k);
            }
        }
    }
    return best;
}

//---------------------------------------------------------
// Scene SDF = distanceToAllWires - TUBE_RADIUS
//---------------------------------------------------------
float getSceneSDF(vec3 p, float time)
{
    DistID dId = distanceToAllWires(p, time);
    return dId.dist - TUBE_RADIUS;
}

//---------------------------------------------------------
// Retrieve DistID for shading
//---------------------------------------------------------
DistID getDistIDAtPoint(vec3 p, float time)
{
    return distanceToAllWires(p, time);
}

//---------------------------------------------------------
// Raymarch
//---------------------------------------------------------
vec3 raymarch(vec3 ro, vec3 rd, float time, out bool hitSomething)
{
    hitSomething = false;
    float distAccum = 0.0;

    for(int i=0; i<MAX_STEPS; i++)
    {
        vec3 pos = ro + rd*distAccum;
        float d  = getSceneSDF(pos, time);
        if(abs(d) < EPSILON)
        {
            hitSomething = true;
            return pos;
        }
        distAccum += d;
        if(distAccum > MAX_DIST) break;
    }
    return ro + rd*MAX_DIST; // fallback if no hit
}

// Normal via central differences
float sampleSDF(vec3 p, float time)
{
    return getSceneSDF(p, time);
}
vec3 getNormal(vec3 p, float time)
{
    float d0 = sampleSDF(p, time);
    vec2 e = vec2(0.001, 0.0);

    float nx = sampleSDF(p + vec3(e.x, e.y, e.y), time) - d0;
    float ny = sampleSDF(p + vec3(e.y, e.x, e.y), time) - d0;
    float nz = sampleSDF(p + vec3(e.y, e.y, e.x), time) - d0;
    return normalize(vec3(nx, ny, nz));
}

//---------------------------------------------------------
// Wire #1 => Yellow
// Wire #2 => White
//---------------------------------------------------------
vec3 getWireColor(float knotId, float wireId)
{
    if(wireId >= 1.5)
    {
        // wire #2 => white
        return vec3(1.0);
    }
    else
    {
        // wire #1 => yellow
        return vec3(1.0, 1.0, 0.0);
    }
}

//---------------------------------------------------------
// MAIN
//---------------------------------------------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized screen coords
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;

    //-------------------------------------------------
    // 1) CAMERA SETUP
    //-------------------------------------------------
    vec3 baseCamPos = vec3(0.0, 0.0, 2.5);
    vec3 baseTarget = vec3(0.0, 0.0, 0.0);

    // Check if the user has moved the mouse
    bool noMouseUsed = (iMouse.x < 1.0 && iMouse.y < 1.0);

    vec3 ro;
    vec3 tg;

    if(noMouseUsed)
    {
        // Auto-spin camera around Y if mouse not used
        float spin = -0.001 * iTime;
        mat3 autoRot = rotateY(spin);

        ro = autoRot * baseCamPos;
        tg = autoRot * baseTarget;
    }
    else
    {
        // Otherwise => user-driven camera
        mat3 camRot = getCameraRotation(iMouse, iResolution.xy);
        ro = camRot * baseCamPos;
        tg = camRot * baseTarget;
    }

    // Build look-at vectors
    vec3 fw    = normalize(tg - ro);
    vec3 right = normalize(cross(fw, vec3(0,1,0)));
    vec3 up    = cross(right, fw);

    // Ray direction
    vec3 rd = normalize( uv.x*right + uv.y*up + fw );

    //-------------------------------------------------
    // 2) RAYMARCH
    //-------------------------------------------------
    bool hitSomething;
    vec3 hitPos = raymarch(ro, rd, iTime, hitSomething);

    // Background color
    vec3 color = vec3(0.77);

    if(hitSomething)
    {
        // Normal
        vec3 n = getNormal(hitPos, iTime);

        // Simple directional light
        vec3 lightDir = normalize(vec3(0.4, 0.7, 0.3));
        float diff = max(dot(n, lightDir), 0.0);
        color = vec3(1.0)*diff + 0.2;

        // Which wire/knot?
        DistID dId = getDistIDAtPoint(hitPos, iTime);

        // Wire color
        vec3 wireColor = getWireColor(dId.knotId, dId.wireId);

        // Combine
        color = mix(color, wireColor, 0.8);
    }

    fragColor = vec4(color, 1.0);
}
